import {nativeIcon} from './interface-icons.js';
import {journeyReport,OUTCOME_NAMES} from './chronicle.js';
import {FACTIONS,factionImage,sourceFaction,unitFaction} from './factions.js';
import {statTier} from './unit-info.js';
import {tierLabel,numericRating} from './math.js';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Math.round(Number(n)||0).toLocaleString('zh-CN');
const statNumber=n=>(Number(n)||0).toLocaleString('zh-CN',{maximumFractionDigits:1});
const button=(title,action,cls='')=>`<button class="${cls}" data-act="${action}">${title}</button>`;
const metric=(name,value,detail='')=>`<div class="chronicle-metric"><span>${name}</span><strong>${number(value)}</strong>${detail?`<small>${detail}</small>`:''}</div>`;
const FIELDS=[['H','生命上限'],['A','体术强度'],['P','源石技艺强度'],['D','防御'],['R','魔抗'],['Emax','技力上限']];
const LABELS={martial:'体术',A:'A招式',B:'B招式',C:'C招式',rest:'休整',defend:'防御',firstAid:'急救',fieldMedical:'野战护理'};

export function endingMarkup(s){
 const r=journeyReport(s),story=r.story,actions=Object.entries(r.actions).filter(([k])=>LABELS[k]),total=actions.reduce((n,[,v])=>n+v,0),max=Math.max(1,...actions.map(([,v])=>v));
 const mostUsed=[...actions].sort((a,b)=>b[1]-a[1])[0];
 const endingKnown=r.wins.length>0||r.attempts>0;
 return `<section class="chronicle-screen ${r.fatal?'chronicle-fatal':''}">
 <header class="chronicle-heading"><div><span class="eyebrow">PRTS / EXPEDITION ARCHIVE</span><h1>旅程归档</h1><p>${esc(s.name)} · ${esc(r.art?.name)}（${esc(r.art?.source)}）</p></div><div class="chronicle-buttons">${button('导出本局档案','export','primary')}${button('项目与致谢','endingThanks','ghost')}${button('返回标题','home','ghost')}</div></header>
 <section class="chronicle-cover"><div class="cover-index" aria-hidden="true">${String(s.nodeIndex+1).padStart(2,'0')}<span>CHAPTER</span></div><div class="cover-main"><span class="eyebrow">${esc(story.subtitle)}</span><h2>${esc(story.title)}</h2><p>${esc(r.start.name)} <span>→</span> ${esc(r.current.name)}</p><div class="chronicle-mode-tags"><span>${s.mode==='campaign'?'连贯战役':'独立节点'}</span><span>${s.iron?'铁人模式':'常规模式'}</span>${s.legend?'<span>传奇之路</span>':''}${s.solo?'<span>一人成军</span>':''}</div></div><div class="cover-mark" aria-hidden="true">${factionImage(FACTIONS.rhodes)}<span>RHODES ISLAND<br>FINAL REPORT</span></div></section>
 ${r.failed?`<section class="notice" role="status"><strong>任务失败 · 本局结束</strong><p>${esc(s.lastResult?.title||r.current.name)}：${esc(s.endingReason||s.lastResult?.reason||'未达成作战目标')}</p></section>`:''}
 <div class="chronicle-summary">${metric('完成作战',r.wins.length,`${r.attempts}次正式出战`)}${metric('Boss击败',r.defeated.length,'按实际退场结果记录')}${metric('完整节点',r.completed.length,`${r.visited.length}处抵达节点`)}${metric('已用准备日',r.days,`${r.vectorWins}/${r.vectorAttempts}次突破获胜`)}</div>
 <div class="chronicle-body"><section class="chronicle-letter"><header><span class="section-number">01</span><h3>终章记述</h3><small>THE ROAD YOU WALKED</small></header>${story.paragraphs.map((p,i)=>`<p class="${i===3?'last-paragraph':''}">${esc(p)}</p>`).join('')}<div class="letter-signature">PRTS 已将这段故事归档<span>${esc(s.name)} / ${esc(s.rolls?.[0]?.name||'起点未详')}</span></div></section>
 <aside class="chronicle-modes"><header><span class="section-number">02</span><h3>你选择的行路规则</h3></header>${story.modes.map(m=>`<article><h4>${esc(m.name)}</h4><p>${esc(m.text)}</p></article>`).join('')}<div class="chronicle-origin"><span>起点档案</span><p>${esc(s.rolls?.[0]?.name||'未详')} · ${esc(s.rolls?.[1]?.name||'未详')}</p><p>${s.identity==='I01'?'感染者':'非感染者'} · 成长天赋 ${esc(s.talent)} ×${s.multiplier}</p></div></aside></div>
 <section class="chronicle-section"><header><span class="section-number">03</span><h3>领袖战果</h3><small>BOSS ENCOUNTERS</small></header><p class="section-caption">记录本场交锋的结果；完成撤离、破坏设施与强制退场分别记载。</p><div class="boss-records">${r.bosses.length?r.bosses.map(b=>`<article class="boss-record ${b.outcome}"><div class="boss-mark" aria-hidden="true">${factionImage(unitFaction({npcId:b.key,name:b.name,side:'enemy'},b.name))||nativeIcon('combat')}</div><div><small>${esc(b.grade)}</small><h4>${esc(b.name)}</h4><p>${esc(b.battle)} · ${number(b.rounds)}轮</p>${b.scope!=='本场作战'?`<p>${esc(b.scope)}</p>`:''}</div><span class="boss-result">${b.outcome==='repelled'?'目标达成<small>未击败</small>':OUTCOME_NAMES[b.outcome]}${!b.won?'<small>本场任务未完成</small>':''}</span></article>`).join(''):`<p class="chronicle-empty">${r.partial?'旧版档案没有保存可核实的Boss战果；后续正式作战会开始记录。':'本段旅程尚未形成Boss遭遇记录。'}</p>`}</div></section>
 <section class="chronicle-section"><header><span class="section-number">04</span><h3>从起点到此刻</h3><small>PERSONNEL PROGRESSION</small></header><div class="chronicle-rating"><span>${r.initial?esc(tierLabel(numericRating(r.initial).score)):'起点未详'}</span><i>→</i><strong>${esc(tierLabel(numericRating(r.final).score))}</strong><em>熟练度 ${s.mastery}/200</em></div><div class="chronicle-growth">${FIELDS.map(([k,label])=>{const before=r.initial?.[k],after=r.final[k],delta=Number.isFinite(before)?Math.round(after*10)/10-Math.round(before*10)/10:null;return `<article><span>${label}</span><div><small>${Number.isFinite(before)?statNumber(before):'未详'}</small><i>→</i><strong>${statNumber(after)}</strong></div><b>${delta===null?'起点未保存':(delta>=0?'+':'')+statNumber(delta)}</b><p>${esc(statTier(r.final,k))}</p></article>`;}).join('')}</div><div class="chronicle-milestones">${r.milestones.length?r.milestones.map(m=>`<span><b>M${m.threshold} · ${m.threshold===100?'专精':'升变'}</b>${m.day!==undefined?'第'+m.day+'准备日 · '+esc(m.title):'已解锁 · 旧记录未保存解锁时点'}</span>`).join(''):'<span>专精与升变仍等待更多熟练度；这段旅程已经积累的成长全部保留在档案中。</span>'}</div></section>
 <section class="chronicle-section"><header><span class="section-number">05</span><h3>战术与日常</h3><small>DECISIONS THAT REMAIN</small></header><p class="section-caption">正式作战统计；矢量突破单独列入日常积累。</p>${r.partial?'<p class="chronicle-data-note">部分作战来自旧版存档，下列详细计数仅包含已保存的记录。</p>':''}<div class="chronicle-tactics"><div><h4>${mostUsed?'最常使用：'+LABELS[mostUsed[0]]:'行动记录'}</h4><p class="section-caption">${total?`博士共作出${number(total)}次有效行动。`:'尚无完整的博士行动计数。'}</p><div class="tactic-bars">${actions.map(([k,n])=>`<div><span>${LABELS[k]}</span><i><em style="width:${n/max*100}%"></em></i><strong>${number(n)}</strong></div>`).join('')}</div></div><div class="chronicle-small-metrics">${metric('我方生命伤害',r.allyDamage,'含友方与召唤物')}${metric('护盾伤害',r.shieldDamage)}${metric('我方治疗',r.healing)}${metric('消耗补给',r.supplies)}${metric('召唤部署',r.summons)}${metric('博士战后获救',r.rescues)}${metric('设施破坏',r.facilities)}${metric('场景炮击',r.shots)}</div></div><div class="chronicle-routine"><p><span>日常积累</span>${r.trainingDays}日锻炼或后勤 · ${r.vectorWins}/${r.vectorAttempts}次矢量突破获胜${r.favoriteTraining?` · 最常项目：${esc(r.favoriteTraining[0])}（${r.favoriteTraining[1]}日）`:''}</p><p><span>行动轨迹</span>${r.rounds}个主线战场轮 · ${r.evacuations}处未完成任务 · ${r.retries}次重试${r.checks?' · '+r.checks+'次身份核验':''}</p>${r.companions.length?`<p><span>曾经同行</span>${r.companions.map(c=>esc(c.name)).join('、')}</p>`:s.solo?'<p><span>独立阵列</span>剧情作战没有编入队友；所有本方召唤物按各自行动逻辑作战。</p>':''}</div></section>
 <section class="chronicle-section"><header><span class="section-number">06</span><h3>旅程留下的刻印</h3><small>MEMORIES</small></header><div class="chronicle-imprints">${r.imprints.length?r.imprints.map((m,i)=>`<article><span aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><h4>${esc(m.name)}</h4><p>${esc(m.detail)}</p></div></article>`).join(''):'<p class="chronicle-empty">这次出发尚未解锁刻印。已经作出的选择，仍被写入时间线。</p>'}</div></section>
 <section class="chronicle-section"><details class="chronicle-timeline" ${endingKnown?'':'open'}><summary>完整行动时间线 <span>${r.attempts}次出战 / ${r.visited.length}处节点</span></summary><ol>${r.visited.map(n=>`<li class="timeline-chapter"><span>${esc(n.id)}</span><strong>${esc(n.name)}</strong><em>${r.completed.some(c=>c.id===n.id)?'四场完成':n.id===r.current.id?'最后抵达':'含撤离记录'}</em></li>${(s.history||[]).filter(h=>h.id.startsWith(n.id+'-')).map(h=>`<li><span>${h.won?'完成':'未完成'}</span><div><strong>${esc(h.title)}</strong><p>${number(h.rounds)}轮 · ${esc(h.reason)}${h.rescued?' · 博士由队伍救回':''}</p></div><em>${h.kind==='objective'&&h.won?'目标达成':h.won?'战场胜利':'撤离／终止'}</em></li>`).join('')}`).join('')}</ol></details></section>
 <footer class="chronicle-close"><p>记录止于此处。下一段旅程，仍由你写下。</p><div>${button('导出本局档案','export','primary')}${button('项目与致谢','endingThanks','ghost')}${button('返回标题','home','ghost')}</div></footer></section>`;
}
